def find_missing_number(nums):
    n = len(nums) + 1
    total = n * (n + 1) // 2
    for num in nums:
        total -= num
    return total

Forward refs, they allow you to pass reference to component. This reference can be used to access component's DOM node. This useful for components that need to access DOM node, like event handlers. Example:

import React, { useRef, forwardRef } from 'react';

const MyComponent = forwardRef((props, ref) => {
  const inputRef = useRef(null);

  const handleInput = (event) => {
    console.log(event.target.value);
  };

  return (
    <input ref={inputRef} onChange={handleInput} />
  );
});

const App = () => {
  const inputRef = useRef(null);

  return (
    <div>
      <MyComponent ref={inputRef} />
      <button onClick={() => inputRef.current.focus()}>Focus input</button>
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById('root'));

